INSERT INTO `agreement` (`Agreement`, `LicenseID`, `ID`) VALUES
	('Ovo je prva faktura koja Vam je poslata od ovog subjekta. Po zakonu, od 1.1.2021 godine „Obveznik može da izda račun u papirnom, odnosno u elektronskom obliku ako postoji saglasnost primaoca da prihvata račun u elektronskom obliku, osim u slučaju obaveze izdavanja računa u elektronskom obliku u skladu sa zakonom kada saglasnost primaoca nije potrebna.”.- član 42. stav 5. Zakona o porezu na dodatu vrednost ("Sl. glasnik RS", br. 84/2004, 86/2004 - ispr., 61/2005, 61/2007, 93/2012, 108/2013, 6/2014 - usklađeni din. izn., 68/2014 - dr. zakon, 142/2014, 5/2015 - usklađeni din. izn., 83/2015, 5/2016 - usklađeni din. izn., 108/2016, 7/2017 - usklađeni din. izn., 113/2017, 13/2018 - usklađeni din. izn., 30/2018, 4/2019 - usklađeni din. izn., 72/2019, 8/2020 - usklađeni din. izn. i 153/2020)', 1, 1);
